import { html, nothing } from 'lit'
import { DsElement, define, HostLayoutController } from '@/elements/lib/element'
import type { ChatContent, BuildContent } from '@/lib/use-case-hero'
import { useCaseContent, type UseCaseContent, useCaseSections, type UseCaseSection, type UseCaseBlocks } from '@/lib/pages/use-case'
import '@/elements/components/site/site-header'
import '@/elements/components/site/use-case-hero'
import '@/elements/components/site/connect-menu'
import '@/elements/components/site/proof-block'
import '@/elements/components/blocks/scroll-story'
import '@/elements/components/blocks/stories-block'
import '@/elements/components/blocks/use-case-wheel'
import '@/elements/components/blocks/faq-block'
import '@/elements/components/site/page-close'
import '@/elements/components/blocks/site-footer'
import '@/elements/components/visuals/dispersion-field'
import '@/elements/components/visuals/ascii-trail'
import styles from 'virtual:tw'
import { pageSections } from '@/lib/image'
import { useCaseWheelContent } from '@/lib/use-case-wheel'
import { headerMenus, type HeaderMenus } from '@/lib/site-header'

// UseCasePage.tsx as <spyglass-use-case-page>: the header, the hero (with the connect menu), the proof line, the scroll
// story, the stories, the wheel with the light around its ring (the field takes the wheel's ripple), the FAQ, the
// closing section and the footer. `content`, `visual`, `chat` and `build` as in React; `still` holds the wheel and its
// light.
const CONTAINER = 'mx-auto w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] px-(--ds-layout-gutter)'

/**
 * @summary A use case's page.
 */
export class UseCasePage extends DsElement {
	static styles = [DsElement.styles, styles]
	protected readonly layout = new HostLayoutController(this, () => this.renderRoot.querySelector<HTMLElement>('[data-ds="use-case-page"]'))
	static properties = { content: { type: Object }, visual: {}, chat: { type: Object }, build: { type: Object }, still: { type: Boolean }, sections: { type: Array }, blocks: { type: Object }, menus: { type: Object } }
	/** The copy as JSON (lib/pages/use-case.ts by default). */
	content: UseCaseContent = useCaseContent
	/** The hero's visual: chat or build. */
	visual: 'chat' | 'build' = 'chat'
	/** The hero chat's session. */
	chat?: ChatContent
	/** The hero's build library. */
	build?: BuildContent
	/** Hold the wheel and its light still. */
	still = false

	updated() {
		const wheel = this.renderRoot.querySelector<HTMLElement & { ripple?: unknown }>('spyglass-use-case-wheel')
		const field = this.renderRoot.querySelector<HTMLElement & { ripple?: unknown }>('spyglass-dispersion-field')
		if (wheel && field && field.ripple !== wheel.ripple) field.ripple = wheel.ripple
	}
	/** The header menus' content, pictures included (the live card's `picture`, the use cases' `shots`); Acme by default. */
	menus?: HeaderMenus
	/** The sections to show, in order (a list of names); all of them in the page order by default. */
	/** Each block's data, pictures included: the story's `story` and the wheel's `items`. */
	blocks: UseCaseBlocks = {}
	sections?: UseCaseSection[]

	render() {
		const c = this.content ?? useCaseContent
		const b = this.blocks ?? {}
		const parts: Record<UseCaseSection, unknown> = {
			hero: html`<spyglass-use-case-hero .content=${c.hero} visual=${this.visual} .chat=${this.chat} .build=${this.build}>${c.control === 'mcp' ? html`<spyglass-connect-menu slot="control"></spyglass-connect-menu>` : nothing}</spyglass-use-case-hero>`,
			proof: html`<spyglass-proof-block head-id=${`${c.slug}-proof`} heading=${c.proof}></spyglass-proof-block>`,
			story: html`<spyglass-scroll-story .story=${b.story?.story} preset=${c.story.preset} .actions=${c.story.actions}></spyglass-scroll-story>`,
			stories: html`<spyglass-stories-block section-id=${`${c.slug}-stories`} headline=${c.stories.headline} lead=${c.stories.lead} .stories=${c.stories.items} customers="false"></spyglass-stories-block>`,
			wheel: html`<spyglass-use-case-wheel section-id="v2-use-cases" .items=${b.wheel?.items ?? useCaseWheelContent.items} .autoplay=${!this.still}><spyglass-dispersion-field slot="light" class="relative block size-full" composition="ring" seed="5" ?still=${this.still}></spyglass-dispersion-field></spyglass-use-case-wheel>`,
			faq: html`<div class=${`${CONTAINER} py-(--ds-layout-section)`}><spyglass-faq-block head-id=${`${c.slug}-faq`} heading=${c.faq.headline} body=${c.faq.lead} .action=${c.faq.docs} .items=${c.faq.items}></spyglass-faq-block></div>`,
			close: html`<spyglass-page-close></spyglass-page-close>`,
		}
		return html`<div data-ds="use-case-page" class="isolate bg-surface text-fg"><spyglass-ascii-trail mode="page"></spyglass-ascii-trail><spyglass-site-header .menus=${this.menus ?? headerMenus} .links=${c.chrome.header.nav} .secondary=${c.chrome.header.secondary} .cta=${c.chrome.header.cta}></spyglass-site-header><main id="main">${pageSections(useCaseSections, this.sections).map((k) => parts[k])}</main><spyglass-site-footer .columns=${c.chrome.footer.columns} legal=${c.chrome.footer.legal}></spyglass-site-footer></div>`
	}
}

define('use-case-page', UseCasePage)
